        ideas: [{ labelUk: "об'єкт зі рядковими ключами", labelEn: "object with string keys", anyOf: ["рядк", "string", "groupby"] }, { labelUk: "Map зберігає тип", labelEn: "Map keeps the type", anyOf: ["map", "тип", "type"] }, { labelUk: "fromEntries і entries", labelEn: "fromEntries and entries", anyOf: ["fromentries", "entries"] }],
        sampleUk: "Object.groupBy будує звичайний об'єкт зі рядковими ключами, а Map.groupBy зберігає ключі будь-якого типу; пари можна збирати назад через fromEntries після Object.entries.",
